import{_t as e,it as t,n,rt as r}from"./chunks/framework.BVGGWBQY.js";var i=JSON.parse(`{"title":"What is carddav-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1788651926000}`),a={name:`guide/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="what-is-carddav-mcp" tabindex="-1">What is carddav-mcp? <a class="header-anchor" href="#what-is-carddav-mcp" aria-label="Permalink to “What is carddav-mcp?”">​</a></h1><p>An MCP server that puts a CardDAV address book in front of a model: seventeen tools over contacts, groups and photos, on any server that speaks the standard.</p><p>CardDAV (<a href="https://datatracker.ietf.org/doc/html/rfc6352" target="_blank" rel="noreferrer">RFC 6352</a>) is WebDAV with vCards in it. It is what Nextcloud, Radicale, Baikal, SOGo, Fastmail, mailbox.org and iCloud all serve, which is the reason to target the protocol rather than any one vendor&#39;s API — one server reaches all of them, and the one you self-host works exactly like the one you pay for.</p><h2 id="what-it-is-for" tabindex="-1">What it is for <a class="header-anchor" href="#what-it-is-for" aria-label="Permalink to “What it is for”">​</a></h2><p>Finding a person and reading their card. Adding somebody, correcting a number, keeping a group up to date. Exporting a book so there is a copy of it somewhere. The things a person actually does with an address book, phrased as tools a model can pick from.</p><h2 id="what-it-is-not-for" tabindex="-1">What it is not for <a class="header-anchor" href="#what-it-is-not-for" aria-label="Permalink to “What it is not for”">​</a></h2><p>Being a sync client. This server reads and writes single cards over HTTP on demand; it keeps no local copy, no cache of contacts, and no state between calls beyond a short-lived list of which address books exist. <code>list_changes</code> exists so that something else can keep state, not so that this can.</p><p>It is also not a merge tool, not a bulk importer, and not a de-duplicator. Those are judgements about people rather than operations on a protocol, and the irreversible half of each of them is the half this server declines to own — see <a href="/guide/security#what-this-server-cannot-do">what it deliberately cannot do</a>.</p><h2 id="the-shape-of-it" tabindex="-1">The shape of it <a class="header-anchor" href="#the-shape-of-it" aria-label="Permalink to “The shape of it”">​</a></h2><p>Every tool is one or two DAV requests and a projection. There is no framework underneath: the WebDAV verbs are a closed list, the XML request bodies are built by hand from a fixed vocabulary, and <code>ical.js</code> is imported in exactly one file. That is small enough to read in an afternoon, which is the property that matters for something holding an address book&#39;s credentials.</p><p>Two decisions run through all of it and are worth knowing before anything else:</p><p><strong>A listing is not a card.</strong> <code>list_contacts</code> asks the server for a dozen named properties rather than for whole cards, because a book of a few hundred contacts with photos is megabytes. What comes back is marked <code>partial</code>, and no write is ever built on one — the write path fetches the whole card itself.</p><p><strong>Everything a card says is somebody else&#39;s writing.</strong> Not only the notes: the name and the organisation too, because those are the fields a reader uses to decide who they are looking at. It is fenced, marked and reported on, never followed. <a href="/guide/security">Security</a> has the detail.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to “Where to go next”">​</a></h2><ul><li><a href="/guide/getting-started">Getting started</a> — the shortest path to a working connection.</li><li><a href="/guide/clients">Connecting clients</a> — Claude Code, Claude Desktop, Codex, Docker, mcp-hub.</li><li><a href="/guide/configuration">Configuration</a> — every variable, and how to narrow the tool list.</li><li><a href="/guide/approval">Asking a person</a> — what the dialog is, what the token fallback proves, and what it does not.</li><li><a href="/reference/tools">Tools reference</a> — the full table, generated from the running server.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};